/** "na Amazon", "na Shopee", "no Mercado Livre", "na loja". */
function naLoja(loja) {
  if (loja === 'ml') return 'no Mercado Livre';
  if (loja === 'amazon' || loja === 'shopee') return 'na ' + NOMES[loja];
  return 'na loja';
