        tipo: `erro_${ch.bot}`,
        texto: `${quem}: o Telegram não conseguiu entregar ao n8n há ${min} min (${String(w.last_error_message || 'sem detalhe').slice(0, 200)}). Veja o túnel e o filtro.`,
